  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_by_id = {}
    children = {}
    root_id = None
    for n in nodes:
        nid = n['id']
        node_by_id[nid] = n
        children.setdefault(nid, [])
        parent = n.get('parent')
        if parent is None:
            root_id = nid
        else:
            children.setdefault(parent, []).append(nid)
    sorted_nodes = sorted(nodes, key=lambda x: (-x['depth'], x['id']))
    from collections import Counter
    total_counts = Counter()
    for n in nodes:
        total_counts[n['symbol']] += 1
    current_counts = total_counts.copy()
    removed = set()
    removal_order = []
    for n in sorted_nodes:
        nid = n['id']
        if nid in removed:
            continue
        if not n.get('removable', False):
            continue
        if nid == root_id:
            continue
        # check retained children
        retained_child = False
        for cid in children.get(nid, []):
            if cid not in removed:
                retained_child = True
                break
        if retained_child:
            continue
        sym = n['symbol']
        ok = True
        for req in required:
            count = current_counts.get(req, 0)
            if req == sym:
                if count - 1 <= 0:
                    ok = False
                    break
            else:
                if count <= 0:
                    ok = False
                    break
        if not ok:
            continue
        current_counts[sym] -= 1
        removed.add(nid)
        removal_order.append(nid)
    retained = sorted([nid for nid in node_by_id if nid not in removed])
    return {'removed_node_ids': removal_order, 'retained_node_ids': retained}
